const body = $input.first().json.body || $input.first().json;
const vendors = body.vendors || (body.website ? [{ vendor_name: body.vendor_name || '', website: body.website }] : []);
if (!vendors.length) return [{ json: { _no_vendors: true } }];
const supabase_url = (body.supabase_url || process.env.SUPABASE_URL || '').trim();
const supabase_key = (body.supabase_key || process.env.SUPABASE_KEY || '').trim();
return vendors.map(v => ({
  json: {
    vendor_name: v.vendor_name || v.name || '',
    website: (v.website || '').replace(/\/$/, ''),
    trustpilot_slug: v.trustpilot_slug || '',
    supabase_url,
    supabase_key,
  }
}));

const item = $input.first().json;
// Use domain slug (e.g. freshdesk.com) — Trustpilot URLs are /review/{domain}
// Prefer explicit trustpilot_slug, then domain from website, then derived from name
let slug = item.trustpilot_slug;
if (!slug && item.website) {
  // Strip protocol and www. to get domain slug
  slug = item.website.replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/$/, '');
}
if (!slug) {
  // Fallback: derive from vendor name
  const clean = (item.vendor_name || '')
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .replace(/[\s-]+/g, '-')
    .trim();
  slug = clean.replace(/^-|-$/g, '');
}
return [{ json: { ...item, trustpilot_slug: slug } }];

const vendor = $('Build Slug').first().json;
const respJson = $input.first().json;
// fullResponse mode: data=body, statusCode available
const html = respJson.data || respJson.body || '';
const statusCode = respJson.statusCode || 200;

if (!html || statusCode !== 200) {
  return [{ json: {
    vendor_name: vendor.vendor_name,
    website: vendor.website,
    trustpilot_slug: vendor.trustpilot_slug,
    _has_data: false,
    _miss_reason: statusCode === 404 ? 'page_not_found' : `http_${statusCode || 'error'}`,
    _http_status: statusCode
  } }];
}

function extractAggregateRating(obj) {
  if (!obj || typeof obj !== 'object') return null;
  if (obj['@type'] === 'AggregateRating' && obj.ratingValue !== undefined) {
    try { return { rating: parseFloat(obj.ratingValue), count: parseInt(obj.reviewCount, 10) }; } catch(e) {}
  }
  if (obj.aggregateRating) { const r = extractAggregateRating(obj.aggregateRating); if (r) return r; }
  if (Array.isArray(obj['@graph'])) { for (const item of obj['@graph']) { const r = extractAggregateRating(item); if (r) return r; } }
  if (Array.isArray(obj)) { for (const item of obj) { const r = extractAggregateRating(item); if (r) return r; } }
  return null;
}

// Extract all JSON-LD blocks and search for AggregateRating
const scriptTags = html.match(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi) || [];
let rating = null;
for (const tag of scriptTags) {
  const content = tag.replace(/<\/?script[^>]*>/gi, '').trim();
  try { const r = extractAggregateRating(JSON.parse(content)); if (r) { rating = r; break; } } catch(e) {}
}

if (!rating) {
  return [{ json: { vendor_name: vendor.vendor_name, website: vendor.website, trustpilot_slug: vendor.trustpilot_slug, _has_data: false, _miss_reason: 'no_rating_found' } }];
}

return [{ json: { vendor_name: vendor.vendor_name, website: vendor.website, trustpilot_slug: vendor.trustpilot_slug, trustpilot_rating: rating.rating, trustpilot_review_count: rating.count, _has_data: true } }];

const item = $input.first().json;

// Build upsert row for /admin/enrich-write
const row = {
  website: item.website,
  trustpilot_rating: item.trustpilot_rating,
  trustpilot_review_count: item.trustpilot_review_count,
  source: 'trustpilot_enrichment',
  pipeline_name: 'trustpilot'
};

return [{ json: { ...item, _upsert_row: row } }];

